actions.script:
const list = (value) => value == null || value === '' ? [] : [].concat(value).map(String).filter(Boolean)
const out = ec.service.sync().name('org.moqui.dev.DatabaseServices.plan#SchemaChanges').parameters({db,
    entityNames: list(context.entityNames), changes: list(context.changes), names: list(context.names),
    description: list(context.entityNames).length == 1 ? 'Indexes and keys of ' + list(context.entityNames)[0] : 'Indexes and keys'}).call() || {}
planJobId = ec.message.hasError() ? null : out.jobId
// no job: nothing to run, or not allowed to run it; the statements are still what would run
if (!planJobId && !ec.message.hasError()) ec.message.addMessage(ec.resource.expand('Not planned as a job: ${reason} (${count} statements)', '',
    {reason: out.jobReason || 'nothing to run', count: (out.statements || []).length}), 'warning')
for (const warning of out.warnings || []) ec.message.addMessage(String(warning), 'warning')

const list = (value) => value == null || value === '' ? [] : [].concat(value).map(String).filter(Boolean)
const out = ec.service.sync().name('org.moqui.dev.DatabaseServices.get#SchemaDdl').parameters({db, entityNames: list(context.entityNames)}).call() || {}
if (!ec.message.hasError()) ec.web.sendTextResponse(String(out.ddlText || ''), 'application/sql', out.fileName || 'schema.sql')
